const examQuestions=[
  {type:'单选题',points:25,knowledge:'虚拟语气',stem:'请选择最恰当的选项，补全句子：If I were you, I _____ take a short break.',options:['will','can','may','would'],answer:3},
  {type:'多选题',points:25,knowledge:'现在完成时的时间状语',stem:'哪些时间表达可以与现在完成时搭配？请选择所有正确选项。',options:['since 2020','for three years','yesterday','last week'],answer:[0,1]},
  {type:'简答题',points:25,knowledge:'since 与 for 的区别',stem:'请简要说明 since 和 for 的用法区别。',placeholder:'用自己的话写出区别……',keywords:['since','for']},
  {type:'综合题',points:25,knowledge:'时态与虚拟语气的综合运用',stem:'阅读并填空：She has lived in this city _____ 2020. If I were her, I _____ join the study group. 请写出两个答案，并简单说明原因。',placeholder:'写出两个填空答案和你的理由……',keywords:['since','would']}
];
const answerState=[null,null,'',''],durationByQuestion=[0,0,0,0],letters=['A','B','C','D'];let current=0,activeAt=Date.now();const startedAt=Date.now();
const $=selector=>document.querySelector(selector);const escapeHtml=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const formatTime=ms=>{const seconds=Math.floor(ms/1000),minutes=Math.floor(seconds/60);return String(minutes).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')};
function commitTime(){const now=Date.now();durationByQuestion[current]+=Math.max(0,now-activeAt);activeAt=now}
function renderTimer(){const elapsed=Date.now()-startedAt;$('#timer').textContent=formatTime(elapsed)}
function answered(index){const answer=answerState[index];return Array.isArray(answer)?answer.length>0:typeof answer==='string'?answer.trim().length>0:answer!==null}
function renderProgress(){$('#progress').innerHTML=examQuestions.map((_,index)=>'<span class="dot '+(answered(index)?'done ':'')+(current===index?'current':'')+'" title="第 '+(index+1)+' 题"></span>').join('')}
function renderQuestion(){const q=examQuestions[current];$('#typeBadge').textContent=q.type;$('#number').textContent=String(current+1).padStart(2,'0');$('#questionSelect').value=String(current);$('#stem').textContent=q.stem;const area=$('#answerArea');if(q.type==='单选题'||q.type==='多选题'){const multiple=q.type==='多选题';area.innerHTML='<p class="hint">'+(multiple?'可选择多个答案':'请选择一个答案')+'</p><fieldset class="options">'+q.options.map((option,i)=>'<label class="option"><input type="'+(multiple?'checkbox':'radio')+'" name="answer" value="'+i+'" '+(multiple?(answerState[current]||[]).includes(i)?'checked':'':answerState[current]===i?'checked':'')+'><span class="letter">'+letters[i]+'</span><span>'+escapeHtml(option)+'</span></label>').join('')+'</fieldset>';area.querySelectorAll('input').forEach(input=>input.onchange=()=>{if(multiple)answerState[current]=[...area.querySelectorAll('input:checked')].map(item=>Number(item.value));else answerState[current]=Number(input.value);renderProgress()})}else{area.innerHTML='<p class="hint">请直接在下方作答。作答期间暂不显示评分和解析。</p><textarea class="answer-textarea" id="writtenAnswer" maxlength="1500" placeholder="'+escapeHtml(q.placeholder)+'"></textarea>';const field=$('#writtenAnswer');field.value=answerState[current];field.oninput=()=>{answerState[current]=field.value;renderProgress()}}$('#prev').disabled=current===0;$('#next').disabled=current===examQuestions.length-1;renderProgress()}
function go(index){if(index<0||index>=examQuestions.length)return;commitTime();current=index;renderQuestion()}
function scoreQuestion(q,answer){if(q.type==='单选题')return answer===q.answer?q.points:0;if(q.type==='多选题'){if(!Array.isArray(answer)||!answer.length)return 0;const correct=answer.every(i=>q.answer.includes(i));return correct?(answer.length===q.answer.length?q.points:12):0}const text=String(answer||'').toLowerCase(),hits=q.keywords.filter(word=>text.includes(word)).length;return hits===q.keywords.length?q.points:hits?12:0}
function finishExam(){commitTime();const endedAt=Date.now();const scores=examQuestions.map((q,i)=>scoreQuestion(q,answerState[i]));const report={date:new Date().toISOString(),totalMs:Math.max(0,endedAt-startedAt),durations:durationByQuestion,answers:answerState,scores,types:examQuestions.map(q=>q.type),knowledge:examQuestions.map(q=>q.knowledge),maxPoints:examQuestions.map(q=>q.points)};localStorage.setItem('advance-exam-report',JSON.stringify(report));location.href='exam-report.html'}
$('#questionSelect').innerHTML=examQuestions.map((q,i)=>'<option value="'+i+'">第 '+String(i+1).padStart(2,'0')+' 题 · '+q.type+'</option>').join('');$('#questionSelect').onchange=event=>go(Number(event.target.value));$('#prev').onclick=()=>go(current-1);$('#next').onclick=()=>go(current+1);$('#finish').onclick=finishExam;$('#back').onclick=()=>location.href='index.html?view=home';renderQuestion();renderTimer();setInterval(renderTimer,1000);
